def medianOperations(nums, target):
    a = sorted(nums)
    mid = len(a) // 2
    cost = abs(a[mid] - target)
    for i in range(mid):
        if a[i] > target:
            cost += a[i] - target
    for i in range(mid + 1, len(a)):
        if a[i] < target:
            cost += target - a[i]
    return cost
